{
  "slug": "check-syncora-stock-on-phone",
  "title": "Spot-Checking a Synced Stock Item on Your Phone",
  "description": "Use a known item and the last successful sync to verify stock information before relying on the mobile dashboard.",
  "category": "Stock and balances",
  "sections": [
    {
      "heading": "Choose one identifiable stock item",
      "body": "Find an item in TallyPrime with a name you can match exactly. Note any variation that distinguishes it from similar items, such as its size or spelling. Record the information you want to compare and the time you read it."
    },
    {
      "heading": "Use the same company in Syncora",
      "body": "Open Stock for the same synced company, find the item and compare the fields that are available. If a report uses date, unit or location filters, compare like with like. Check the latest successful sync before using the figure."
    },
    {
      "heading": "Investigate a mismatch with a concrete example",
      "body": "Record precisely which field differs and whether a purchase, sale or adjustment happened after the successful sync. Give the accounting team the item name, company and relevant dates. Use TallyPrime to confirm the figure if an urgent decision depends on it."
    }
  ],
  "relatedPaths": [
    "/product-overview",
    "/guides/tally-ledger-on-mobile"
  ]
}
